function cheapestTotal(prices: number[]): number {
  let best = Infinity;
  const used = new Array(prices.length).fill(false);
  const order: number[] = [];
  const cost = (): number => {
    let total = 0;
    for (let i = 0; i < order.length; i += 3) {
      const g = order.slice(i, i + 3);
      total += g.reduce((a, b) => a + b, 0) - (g.length === 3 ? Math.min(...g) : 0);
    }
    return total;
  };
  const go = (): void => {
    if (order.length === prices.length) { best = Math.min(best, cost()); return; }
    for (let i = 0; i < prices.length; i++) {
      if (used[i]) continue;
      used[i] = true; order.push(prices[i]);
      go();
      used[i] = false; order.pop();
    }
  };
  go();
  return best;
}

