class Solution:
    def cheapestTotal(self, prices: List[int]) -> int:
        from itertools import permutations

        best = float("inf")
        for order in permutations(prices):
            total = 0
            for i in range(0, len(order), 3):
                g = order[i : i + 3]
                total += sum(g) - (min(g) if len(g) == 3 else 0)
            best = min(best, total)
        return best

